namespace SwarmCore.Abstractions.LlmRouting;

/// <summary>
/// A benchmark case specification that can be generated by an agent and executed
/// by an optimization service to tune LLM routing for a set of function types.
/// </summary>
public class LlmOptimizationCaseSpec
{
    public required string Name { get; set; }
    public required string Prompt { get; set; }
    public int Pass { get; set; } = 1;
    public double Weight { get; set; } = 1.0d;
    public bool ForceJson { get; set; } = true;
    public string? ExpectedFormat { get; set; } = "json";
    public int? MaxTokens { get; set; } = 220;
    public float? Temperature { get; set; } = 0.1f;
    public List<string> RequiredJsonFields { get; set; } = ["Decision", "Confidence", "Reason"];
    public List<string>? AllowedDecisionValues { get; set; }
    public List<string>? ReasonMustContainAny { get; set; }
}

/// <summary>
/// Request to optimize LLM routing for one or more function types.
/// </summary>
public class LlmRoutingOptimizationRequest
{
    public required IReadOnlyList<string> FunctionTypes { get; set; }
    public required IReadOnlyList<LlmOptimizationCaseSpec> Cases { get; set; }
    public bool ApplyRecommendations { get; set; } = false;
    public string? ApplyUserId { get; set; }
    public bool IncludeOnlyHealthyProviders { get; set; } = true;
    public bool DiscoverProviderModels { get; set; } = true;
    public bool ValidateModelUsability { get; set; } = true;
    public int MaxModelsPerProvider { get; set; } = 1;
    public int ShortlistCountAfterPass1 { get; set; } = 2;
}

public class LlmRoutingOptimizationCandidateResult
{
    public required string Provider { get; set; }
    public required string Model { get; set; }
    public required double Validity { get; set; }
    public required double Accuracy { get; set; }
    public required long AvgLatencyMs { get; set; }
    public required decimal AvgCost { get; set; }
    public required int ErrorCount { get; set; }
}

public class LlmRoutingOptimizationFunctionResult
{
    public required string FunctionType { get; set; }
    public required string RecommendedProvider { get; set; }
    public required string RecommendedModel { get; set; }
    public string? FallbackProvider { get; set; }
    public string? FallbackModel { get; set; }
    public List<LlmRoutingOptimizationCandidateResult> Rankings { get; set; } = [];
}

public class LlmRoutingOptimizationResult
{
    public DateTime TimestampUtc { get; set; } = DateTime.UtcNow;
    public List<(string Provider, string Model)> Candidates { get; set; } = [];
    public List<LlmRoutingOptimizationFunctionResult> Functions { get; set; } = [];
}

/// <summary>
/// Executes benchmark-driven optimization and optionally applies model preferences.
/// </summary>
public interface ILlmRoutingOptimizationService
{
    Task<LlmRoutingOptimizationResult> OptimizeAsync(
        LlmRoutingOptimizationRequest request,
        CancellationToken cancellationToken = default);
}
